import{i as e,r as t,s as n,t as r}from"./app-DuH0mZgh.js";var i=JSON.parse(`{"path":"/20-DevOps_and_Monitoring.html","title":"DevOps 与监控设计","lang":"en-US","frontmatter":{},"filePathRelative":"20-DevOps_and_Monitoring.md","git":{"createdTime":1765122408000,"updatedTime":1765122408000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`20-DevOps_and_Monitoring.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="devops-与监控设计" tabindex="-1"><a class="header-anchor" href="#devops-与监控设计"><span>DevOps 与监控设计</span></a></h1><blockquote><p>目标：定义 Apollo MMO 的构建/测试/发布/监控体系，覆盖 CI/CD、日志、指标、告警、治理流程，确保框架落地后可运维。</p></blockquote><h2 id="_1-ci-cd-流程" tabindex="-1"><a class="header-anchor" href="#_1-ci-cd-流程"><span>1. CI/CD 流程</span></a></h2><h3 id="_1-1-构建" tabindex="-1"><a class="header-anchor" href="#_1-1-构建"><span>1.1 构建</span></a></h3><ul><li>使用 CMake Presets + vcpkg manifest；CI 环境（GitHub Actions/GitLab CI）构建 Windows + Linux 版本。</li><li>静态分析：clang-tidy、cppcheck、clang-format。</li><li>单元测试：Catch2；集成测试使用 gTest 或自研框架。</li><li>代码覆盖率：LLVM/GCov，阈值需达成（例如 &gt;70% 核心模块）。</li></ul><h3 id="_1-2-测试阶段" tabindex="-1"><a class="header-anchor" href="#_1-2-测试阶段"><span>1.2 测试阶段</span></a></h3><table><thead><tr><th>阶段</th><th>内容</th></tr></thead><tbody><tr><td>UT (Unit Test)</td><td>单元测试、Mock DataProxy/Transport</td></tr><tr><td>IT (Integration)</td><td>NetCore/AOI/DB 模块集成</td></tr><tr><td>ST (System)</td><td>端到端测试环境（Gate+Zone+DB）</td></tr><tr><td>PT (Performance)</td><td>压测工具（wrk、Locust、custom C++ client）</td></tr></tbody></table><h3 id="_1-3-发布" tabindex="-1"><a class="header-anchor" href="#_1-3-发布"><span>1.3 发布</span></a></h3><ul><li>使用 <code>release manifest</code>，描述需要部署的服务版本、配置、依赖。</li><li>灰度发布：支持按大区/机房/玩家段逐步发布。</li><li>回滚机制：版本+配置可快速回退；数据库迁移需双向脚本。</li><li>配置管理：版本化（git/配置中心），发布前校验与审批。</li></ul><h2 id="_2-监控与指标" tabindex="-1"><a class="header-anchor" href="#_2-监控与指标"><span>2. 监控与指标</span></a></h2><h3 id="_2-1-指标体系" tabindex="-1"><a class="header-anchor" href="#_2-1-指标体系"><span>2.1 指标体系</span></a></h3><ul><li>Prometheus 作为统一收集器，Grafana 展示；各服务暴露 <code>/metrics</code>（或 gRPC metrics）。</li><li>指标类别： <ul><li><strong>系统</strong>：CPU、内存、IO、FD、线程。</li><li><strong>网络</strong>：连接数、带宽、RTT、重传、限流次数（来自 NetCore）。</li><li><strong>业务</strong>：在线人数、场景数量、AOI 事件延迟、任务队列长度。</li><li><strong>数据层</strong>：DataProxy 队列、Redis 命中率、MySQL QPS、慢查询。</li><li><strong>日志</strong>：TLog 写入速率、Kafka backlog。</li></ul></li></ul><h3 id="_2-2-采集方式" tabindex="-1"><a class="header-anchor" href="#_2-2-采集方式"><span>2.2 采集方式</span></a></h3><ul><li>使用 Prometheus exporter (自研) 或 <code>prometheus-cpp</code>，在每个服务内嵌。</li><li>系统指标可借助 node_exporter/telegraf。</li><li>重要定时任务（如场景创建、AOI shard）也通过事件计数器记录。</li></ul><h2 id="_3-日志与追踪" tabindex="-1"><a class="header-anchor" href="#_3-日志与追踪"><span>3. 日志与追踪</span></a></h2><h3 id="_3-1-日志" tabindex="-1"><a class="header-anchor" href="#_3-1-日志"><span>3.1 日志</span></a></h3><ul><li>spdlog + fmt 封装统一 API（不同级别：trace/debug/info/warn/error/fatal）。</li><li>日志格式 JSON（包含 timestamp, level, server_id, trace_id, message）。</li><li>日志轮转、异步写入；输出到本地文件 + FluentBit/Filebeat -&gt; ELK。</li><li>日志分级：运行日志、访问日志（API）、安全日志（鉴权）、TLog（业务流水）。</li></ul><h3 id="_3-2-分布式追踪" tabindex="-1"><a class="header-anchor" href="#_3-2-分布式追踪"><span>3.2 分布式追踪</span></a></h3><ul><li>使用 OpenTelemetry/Jaeger，埋点 NetCore、Transport、DataProxy、AOI/Zone 等关键链路。</li><li>Trace ID 注入到内部 gRPC/HTTP header；客户端 SDK 也可生成 trace。</li></ul><h2 id="_4-告警与自愈" tabindex="-1"><a class="header-anchor" href="#_4-告警与自愈"><span>4. 告警与自愈</span></a></h2><h3 id="_4-1-告警规则" tabindex="-1"><a class="header-anchor" href="#_4-1-告警规则"><span>4.1 告警规则</span></a></h3><table><thead><tr><th>场景</th><th>告警条件</th></tr></thead><tbody><tr><td>服务不可用</td><td>健康检查失败/Consul 下线</td></tr><tr><td>网络异常</td><td>连接丢包率、高 RTT</td></tr><tr><td>数据层</td><td>MySQL 延迟、Redis 读写失败、DataProxy 队列堆积</td></tr><tr><td>业务</td><td>在线人数骤降、AOI 事件延迟超阈、TLog backlog</td></tr></tbody></table><h3 id="_4-2-告警通道" tabindex="-1"><a class="header-anchor" href="#_4-2-告警通道"><span>4.2 告警通道</span></a></h3><ul><li>Grafana Alert、PagerDuty、企业 WeChat/Slack。</li><li>分级（P1/P2/P3），不同级别触发不同响应流程。</li></ul><h3 id="_4-3-自愈策略" tabindex="-1"><a class="header-anchor" href="#_4-3-自愈策略"><span>4.3 自愈策略</span></a></h3><ul><li>自动重启服务（容器/系统级），结合 Kubernetes/Nomad。</li><li>数据队列堆积自动扩容消费节点。</li><li>限流开关：在指标异常时自动开启部分限流/维护模式。</li></ul><h2 id="_5-运维流程" tabindex="-1"><a class="header-anchor" href="#_5-运维流程"><span>5. 运维流程</span></a></h2><h3 id="_5-1-配置与发布" tabindex="-1"><a class="header-anchor" href="#_5-1-配置与发布"><span>5.1 配置与发布</span></a></h3><ul><li>所有配置/脚本由 Git 管理，发布前必须 PR + Review。</li><li>使用基础设施工具（Ansible/Terraform）部署环境；生产环境自动化程度 &gt; 90%。</li><li>每次发布记录于 Release Log（版本、操作人、时间、说明）。</li></ul><h3 id="_5-2-故障处置" tabindex="-1"><a class="header-anchor" href="#_5-2-故障处置"><span>5.2 故障处置</span></a></h3><ul><li>定义 SOP（日志收集、抓取核心指标、回滚/重启步骤）。</li><li>提供一键打包诊断信息的脚本（日志、配置、核心转储）。</li><li>定期复盘与问题库，沉淀经验。</li></ul><h2 id="_6-环境划分" tabindex="-1"><a class="header-anchor" href="#_6-环境划分"><span>6. 环境划分</span></a></h2><ul><li><strong>Dev</strong>：开发自测，频繁部署。</li><li><strong>Test</strong>：集成测试 + QA。</li><li><strong>Staging</strong>：接近生产，执行压测/灰度。</li><li><strong>Prod</strong>：生产。</li><li>每个环境维护独立配置/资源，支持一键初始化、数据脱敏。</li></ul><h2 id="_7-工具与自动化" tabindex="-1"><a class="header-anchor" href="#_7-工具与自动化"><span>7. 工具与自动化</span></a></h2><ul><li><strong>部署</strong>：Kubernetes 或自研调度（Consul + Nomad）。脚本化提供一键启动/停止整个集群。</li><li><strong>压测平台</strong>：内建压测工具（模拟客户端），支持回放日志/脚本。</li><li><strong>运营工具</strong>：仪表盘显示在线人数、服务器状态、热点场景等信息。</li><li><strong>调试工具</strong>：抓包、流量复制、在线参数调整。</li></ul><h2 id="_8-安全与合规" tabindex="-1"><a class="header-anchor" href="#_8-安全与合规"><span>8. 安全与合规</span></a></h2><ul><li>接入审计：所有运维操作（API/SSH）都记录并可追溯。</li><li>权限管理：RBAC，最小权限原则，运维账号分级。</li><li>数据保护：敏感数据加密存储/传输；脱敏工具用于测试环境。</li></ul><h2 id="_9-roadmap" tabindex="-1"><a class="header-anchor" href="#_9-roadmap"><span>9. Roadmap</span></a></h2><ol><li>完成 CI/CD Pipeline（构建 + 测试 + 发布）。</li><li>集成 Prometheus/Grafana，发布基础指标。</li><li>建立日志采集链路（spdlog → FluentBit → ELK）。</li><li>引入 OpenTelemetry/Jaeger 追踪。</li><li>自动化部署/扩容工具上线，制定灾备演练计划。</li><li>完成告警策略和自愈脚本，定期执行演练。</li></ol><hr><p>该文档为 DevOps/运维团队提供指导，确保 Apollo 框架具备工程化可维护性。***</p>`,41)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};